public class Decide {
    public static void main(String[] args) {
        int score = 82;
        String grade;
        if (score >= 90) {
            grade = "A";
        } else if (score >= 75) {
            grade = "B";
        } else {
            grade = "C";
        }

        String cmd = "stop";
        int code = switch (cmd) {
            case "start", "run" -> 1;
            case "stop" -> {
                System.out.println("stopping...");
                yield 0;
            }
            default -> -1;
        };
        System.out.println(grade + " " + code); // B 0
    }
}

public class Loops {
    public static void main(String[] args) {
        int sum = 0;
        for (int i = 1; i <= 10; i++) {
            if (i % 2 == 0) continue;   // skip even numbers
            sum += i;
        }
        System.out.println(sum);        // 25 (1 + 3 + 5 + 7 + 9)

        int n = 1;
        while (n < 100) n *= 3;         // 1, 3, 9, 27, 81, 243
        System.out.println(n);          // 243

        int tries = 0;
        do {
            tries++;
            if (tries == 3) break;      // stop early
        } while (true);
        System.out.println(tries);      // 3
    }
}

import java.util.Arrays;

public class ArraysDemo {
    public static void main(String[] args) {
        int[] nums = {5, 3, 9, 1};
        int[] alias = nums;              // same array, not a copy
        int[] copy = Arrays.copyOf(nums, nums.length);

        Arrays.sort(nums);
        System.out.println(Arrays.toString(alias)); // [1, 3, 5, 9]
        System.out.println(Arrays.toString(copy));  // [5, 3, 9, 1]

        int max = copy[0];
        for (int n : copy) max = Math.max(max, n);  // for-each: n is each value in turn
        System.out.println(max + " of " + copy.length); // 9 of 4

        int[][] grid = new int[2][3];    // 2 rows, 3 columns
        grid[1][2] = 7;
        System.out.println(Arrays.deepToString(grid)); // [[0, 0, 0], [0, 0, 7]]
    }
}

import java.util.Arrays;

public class Methods {
    static int sum(int... values) {          // varargs
        int total = 0;
        for (int v : values) total += v;
        return total;
    }
    static String describe(int n) { return "int " + n; }
    static String describe(String s) { return "text " + s; } // overload

    static void tryToChange(int x, int[] arr) {
        x = 99;               // changes the local copy only
        arr[0] = 99;          // mutates the caller's array
        arr = new int[]{-1};  // rebinds the local reference only
    }

    public static void main(String[] args) {
        System.out.println(sum(1, 2, 3) + " " + describe(7) + " " + describe("hi")); // 6 int 7 text hi
        int x = 1;
        int[] arr = {1};
        tryToChange(x, arr);
        System.out.println(x + " " + Arrays.toString(arr)); // 1 [99]
    }
}

public class Boxing {
    public static void main(String[] args) {
        int port = Integer.parseInt("8080");
        double ratio = Double.parseDouble("0.75");
        System.out.println(port + ratio);          // 8080.75

        Integer a = 1000, b = 1000;
        System.out.println(a == b);                // false (two separate objects)
        System.out.println(a.equals(b));           // true

        Integer missing = null;                    // allowed: a wrapper can be null
        int safe = (missing != null) ? missing : 0;
        System.out.println(safe);                  // 0
        // int crash = missing;                    // would throw NullPointerException

        try {
            Integer.parseInt("12abc");
        } catch (NumberFormatException e) {
            System.out.println("not a number");    // this line runs
        }
    }
}

