import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Records {
    record Point(int x, int y) {
        Point {                                   // compact constructor
            if (x < 0 || y < 0) throw new IllegalArgumentException("negative");
        }
        double distanceTo(Point o) { return Math.hypot(x - o.x, y - o.y); }
    }
    record Order(String id, List<String> items) {
        Order { items = List.copyOf(items); }     // defensive copy
    }

    public static void main(String[] args) {
        var a = new Point(3, 4);
        System.out.println(a);                    // Point[x=3, y=4]
        System.out.println(a.x() + " " + a.distanceTo(new Point(0, 0))); // 3 5.0

        Set<Point> seen = new HashSet<>();
        seen.add(new Point(1, 2));
        System.out.println(seen.contains(new Point(1, 2))); // true: value equality
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.StringReader;

public class Errors {
    static class ConfigException extends RuntimeException {
        ConfigException(String msg, Throwable cause) { super(msg, cause); }
    }
    static int readPort(String text) {
        try (var reader = new BufferedReader(new StringReader(text))) {
            return Integer.parseInt(reader.readLine().strip());
        } catch (IOException | NumberFormatException e) {
            throw new ConfigException("invalid port: " + text, e); // keep the cause
        }
    }

    public static void main(String[] args) {
        System.out.println(readPort("8080"));          // 8080
        try {
            readPort("eighty");
        } catch (ConfigException e) {   // invalid port: eighty <- NumberFormatException
            System.out.println(e.getMessage() + " <- " + e.getCause().getClass().getSimpleName());
        }
    }
}

concepts.body:
**Generics** let a class or method work with a type that is chosen by the user. `List<String>` is a list that holds only strings: the compiler rejects `add(42)` and `get` returns a `String` with no cast. Before generics (Java 5), collections held `Object` and every read needed a cast that could fail while the program ran.

The **diamond** `<>` lets the compiler infer type arguments: `Map<String, List<Integer>> m = new HashMap<>();`.

Type arguments must be **reference types**, not primitives: write `List<Integer>`, not `List<int>`; autoboxing handles the conversion.

Writing your own generic class is simple — declare a type parameter after the name:

```java
class Box<T> {
    private T value;
    void set(T v) { value = v; }
    T get() { return value; }
}
```

By convention type parameters are single capital letters: `T` (type), `E` (element), `K`/`V` (key/value), `R` (result).

A **generic method** declares its own type parameter before the return type: `static <T> T firstOrNull(List<T> list)`. The compiler infers `T` from the arguments at each call site.

You can restrict a type parameter with a **bound**: `<T extends Comparable<T>>` means "any T that can compare itself to another T", which lets the method call `compareTo`.

Avoid **raw types** like plain `List` without a type argument. They exist only for compatibility with ancient code, disable the checks and produce "unchecked" warnings. Wildcard types (`? extends`, `? super`) and how generics work inside the JVM are covered in the advanced generics lesson.

concepts.code:
import java.util.List;

public class GenericsDemo {
    record Pair<A, B>(A first, B second) { }          // generic record

    static <T> T firstOrDefault(List<T> list, T fallback) {
        return list.isEmpty() ? fallback : list.get(0);
    }

    static <T extends Comparable<T>> T max(List<T> list) {
        T best = list.get(0);
        for (T item : list) if (item.compareTo(best) > 0) best = item;
        return best;
    }

    public static void main(String[] args) {
        var p = new Pair<>("age", 42);                // Pair<String, Integer>
        int age = p.second();                         // no cast needed
        System.out.println(p + " " + age);            // Pair[first=age, second=42] 42
        System.out.println(firstOrDefault(List.<String>of(), "none")); // none
        System.out.println(max(List.of(3, 9, 4)));    // 9
        System.out.println(max(List.of("pear", "apple"))); // pear
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class ListsDemo {
    record Person(String name, int age) { }

    public static void main(String[] args) {
        List<Person> people = new ArrayList<>(List.of(
                new Person("Cy", 41), new Person("Ana", 29), new Person("Bo", 29)));

        people.sort(Comparator.comparing(Person::age).thenComparing(Person::name));
        System.out.println(people.getFirst().name());    // Ana  (Java 21)
        people.removeIf(p -> p.age() > 40);
        System.out.println(people.size());               // 2

        List<Integer> nums = new ArrayList<>(List.of(5, 1, 7));
        nums.remove(1);                                  // removes index 1 -> [5, 7]
        nums.remove(Integer.valueOf(7));                 // removes value 7 -> [5]
        System.out.println(nums);                        // [5]

        List<String> fixed = List.of("x", "y");          // fixed.add("z") would throw
        System.out.println(fixed.reversed());            // [y, x]
    }
}

import java.util.*;

public class MapsSets {
    record Coord(int x, int y) { }                    // correct equals/hashCode for free

    public static void main(String[] args) {
        String text = "the cat and the hat and the bat";
        Map<String, Integer> counts = new TreeMap<>();
        for (String w : text.split(" ")) counts.merge(w, 1, Integer::sum);
        System.out.println(counts);   // {and=2, bat=1, cat=1, hat=1, the=3}

        Map<Integer, List<String>> byLength = new HashMap<>();
        for (String w : counts.keySet()) {
            byLength.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);
        }
        System.out.println(byLength.get(3));          // [and, bat, cat, hat, the]

        Set<Coord> visited = new HashSet<>();
        visited.add(new Coord(1, 2));
        System.out.println(visited.add(new Coord(1, 2)));  // false: already present
        System.out.println(counts.getOrDefault("dog", 0)); // 0
    }
}

import java.util.List;
import java.util.function.*;

public class Lambdas {
    public static void main(String[] args) {
        Predicate<String> isBlank = String::isBlank;
        Predicate<String> hasContent = isBlank.negate();
        Function<String, Integer> length = String::length;
        Function<String, String> shout = s -> s.toUpperCase() + "!";
        Supplier<List<String>> names = () -> List.of("ana", " ", "bo");
        BinaryOperator<Integer> add = Integer::sum;

        int minLength = 2;                 // effectively final: captured below
        Predicate<String> longEnough = s -> s.length() >= minLength;

        for (String n : names.get()) {
            if (hasContent.and(longEnough).test(n)) {
                System.out.println(shout.andThen(length).apply(n) + " " + shout.apply(n));
            }
        }
        // 4 ANA!
