import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.Supplier;

public class Wildcards {
    static double sum(List<? extends Number> nums) {          // producer: extends
        double total = 0;
        for (Number n : nums) total += n.doubleValue();
        return total;
    }
    static void addOnes(List<? super Integer> sink, int count) { // consumer: super
        for (int i = 0; i < count; i++) sink.add(1);
    }
    static <T> T make(Supplier<T> factory) { return factory.get(); } // instead of new T()
    public static void main(String[] args) {
        System.out.println(sum(List.of(1, 2.5, 3L)));   // 6.5
        List<Number> numbers = new ArrayList<>();
        addOnes(numbers, 2);                             // List<Number> accepts Integers
        System.out.println(numbers);                     // [1, 1]
        List<String> words = new ArrayList<>(List.of("b", "a"));
        words.sort(Comparator.comparing(Object::toString)); // Comparator<? super String>
        System.out.println(make(StringBuilder::new).append(words)); // [a, b]
    }
}

concepts.body:
Java 21 finalised a set of features for **data-oriented programming**: keeping data in plain records and writing the logic in separate methods that inspect it. At its core is **pattern matching**: testing what shape a value has and pulling out its parts in one step.

**Pattern matching for instanceof** tests and binds in one step, removing the cast: `if (obj instanceof String s && !s.isEmpty()) { use(s); }`.

A **sealed** class or interface lists exactly which types may extend it:

```java
sealed interface Shape permits Circle, Rect, Triangle { }
record Circle(double r) implements Shape { }
```

Permitted subclasses must be `final`, `sealed` or `non-sealed` (records are implicitly final). Because the compiler knows every permitted type, it can check that a switch is exhaustive.

**Pattern matching for switch** lets each `case` match on type, and **record patterns** take records apart into their components, even nested ones:

```java
double area = switch (shape) {
    case Circle(double r) -> Math.PI * r * r;
    case Rect(double w, double h) -> w * h;
    case Triangle t -> t.area();
};
```

No `default` is needed: the switch over a sealed type is exhaustive. When someone adds a new permitted type, every such switch stops compiling until it handles it — the same safety you get with enums, now for whole data hierarchies.

A `case` can add a **guard** with `when`: `case Rect(double w, double h) when w == h -> "square";`. Order matters: the compiler rejects a case that is dominated by an earlier, more general one. A switch with patterns can also handle `case null` explicitly; otherwise a null selector throws `NullPointerException`.

`var` works inside patterns (`case Rect(var w, var h)`). Unnamed patterns `_` are a preview in Java 21 and final in 22.

This style complements, rather than replaces, polymorphism: use overridden methods when behaviour belongs with the type, and sealed types plus switch when operations live outside the data — for example evaluating a calculator's expression tree, or handling the different kinds of reply another program can send.

concepts.code:
public class Patterns {
    sealed interface Shape permits Circle, Rect, Group { }
    record Circle(double r) implements Shape { }
    record Rect(double w, double h) implements Shape { }
    record Group(Shape a, Shape b) implements Shape { }
    static double area(Shape s) {
        return switch (s) {                       // exhaustive: no default
            case Circle(double r) -> Math.PI * r * r;
            case Rect(double w, double h) -> w * h;
            case Group(Shape a, Shape b) -> area(a) + area(b);
        };
    }
    static String describe(Object o) {
        return switch (o) {
            case null -> "nothing";
            case Rect(var w, var h) when w == h -> "square of side " + w;
            case Rect r -> "rectangle " + r.w() + "x" + r.h();
            default -> "something else";
        };
    }
    public static void main(String[] args) {
        System.out.printf("%.2f%n", area(new Group(new Circle(1), new Rect(2, 3)))); // 9.14
        System.out.println(describe(new Rect(2, 2)) + " / " + describe(null)); // square of side 2.0 / nothing
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class Races {
    static int unsafeCount = 0;
    static final AtomicInteger safeCount = new AtomicInteger();
    static final ConcurrentHashMap<String, Integer> hits = new ConcurrentHashMap<>();
    public static void main(String[] args) throws InterruptedException {
        List<Thread> threads = new ArrayList<>();
        for (int t = 0; t < 4; t++) {
            threads.add(Thread.ofPlatform().start(() -> {
                for (int i = 0; i < 100_000; i++) {
                    unsafeCount++;                       // data race: may lose updates
                    safeCount.incrementAndGet();         // atomic
                    hits.merge("home", 1, Integer::sum); // atomic per key
                }
            }));
        }
        for (Thread th : threads) th.join();
        // unsafeCount is unpredictable (often < 400000); the other two are always 400000
        System.out.println(unsafeCount + " " + safeCount.get() + " " + hits.get("home"));
    }
}

import java.util.List;
import java.util.concurrent.*;

public class Pools {
    static long countPrimes(int from, int to) {
        long n = 0;
        for (int i = Math.max(2, from); i < to; i++) {
            boolean prime = true;
            for (int d = 2; (long) d * d <= i && prime; d++) prime = i % d != 0;
            if (prime) n++;
        }
        return n;
    }
    public static void main(String[] args) throws Exception {
        try (ExecutorService pool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors())) {
            List<Callable<Long>> chunks = List.of(() -> countPrimes(0, 500_000), () -> countPrimes(500_000, 1_000_000));
            long total = 0;
            for (Future<Long> f : pool.invokeAll(chunks)) total += f.get();
            System.out.println(total);                       // 78498
            Future<String> slow = pool.submit(() -> { Thread.sleep(5_000); return "late"; });
            try { slow.get(100, TimeUnit.MILLISECONDS); }
            catch (TimeoutException e) { slow.cancel(true); System.out.println("gave up"); }
        } // close(): waits for remaining tasks, then shuts down
    }
}

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executors;

public class Async {
    record User(String id, String name) { }

    static User fetchUser(String id) { sleep(200); return new User(id, "Ana"); }
    static int fetchOrderCount(String id) { sleep(300); return 7; }
    static double fetchRating(String id) { throw new IllegalStateException("rating service down"); }
    static void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }

    public static void main(String[] args) {
        try (var io = Executors.newVirtualThreadPerTaskExecutor()) {
            var user = CompletableFuture.supplyAsync(() -> fetchUser("u1"), io);
            var orders = CompletableFuture.supplyAsync(() -> fetchOrderCount("u1"), io);
            var rating = CompletableFuture.supplyAsync(() -> fetchRating("u1"), io)
                    .exceptionally(ex -> -1.0);              // fallback on failure

            String summary = user.thenCombine(orders, (u, n) -> u.name() + " has " + n + " orders")
                    .thenCombine(rating, (s, r) -> s + ", rating " + r)
                    .join();                                 // ~300 ms total, not 500
            System.out.println(summary);                     // Ana has 7 orders, rating -1.0
        }
    }
}

import java.time.Duration;
import java.time.Instant;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;

public class Virtual {
    static final Semaphore DB_PERMITS = new Semaphore(1_000); // limit concurrency, don't pool
    static String query(int id) throws InterruptedException {
        DB_PERMITS.acquire();
        try { Thread.sleep(Duration.ofMillis(100)); return "row " + id; } // simulated blocking I/O
        finally { DB_PERMITS.release(); }
    }

    public static void main(String[] args) {
        Instant start = Instant.now();
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 10_000; i++) {
                int id = i;
                executor.submit(() -> query(id));             // one virtual thread per task
            }
        } // waits for all tasks
        // ~1 s: 10,000 calls x 100 ms with at most 1,000 in flight (sequential: ~17 min)
        System.out.println(Duration.between(start, Instant.now()).toSeconds() + " s");
    }
}

