public class MiniRouter {
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD)
    @interface Route { String value(); }

    public static class Handlers {
        @Route("/home") public String home() { return "Welcome"; }
        @Route("/about") public String about() { return "About us"; }
        public String helper() { return "not routed"; }
    }

    public static void main(String[] args) throws Exception {
        var target = new Handlers();
        Method[] methods = Handlers.class.getDeclaredMethods();
        Arrays.sort(methods, Comparator.comparing(Method::getName)); // order is unspecified
        for (Method m : methods) {
            Route r = m.getAnnotation(Route.class);
            if (r != null) System.out.println(r.value() + " -> " + m.invoke(target));
        } // prints "/about -> About us" then "/home -> Welcome"
    }
}

