public class Visibility {
    // Without volatile, the worker may never observe running = false.
    private static volatile boolean running = true;

    // Lazy, thread-safe singleton via class initialization (no locks needed)
    static final class Config {
        private Config() { System.out.println("loading config"); }
        private static final class Holder { static final Config INSTANCE = new Config(); }
        static Config get() { return Holder.INSTANCE; }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread worker = Thread.ofPlatform().start(() -> {
            long spins = 0;
            while (running) spins++;           // volatile read each iteration
            System.out.println("stopped after " + (spins > 0 ? "some" : "no") + " spins");
        });
        Thread.sleep(100);
        running = false;                       // volatile write: happens-before the next read
        worker.join();                         // worker's actions happen-before join returns

        System.out.println(Config.get() == Config.get()); // loading config, then true
    }
}

import java.lang.management.ManagementFactory;
import java.util.HashMap;
import java.util.Map;

// Run with: java -XX:+UseG1GC -Xmx64m -Xlog:gc Leak.java
public class Leak {
    // A static map is a GC root path: everything in it stays reachable forever.
    static final Map<Integer, byte[]> CACHE = new HashMap<>();

    public static void main(String[] args) {
        for (var gc : ManagementFactory.getGarbageCollectorMXBeans()) {
            System.out.println("collector: " + gc.getName());   // e.g. G1 Young Generation
        }
        for (int i = 0; i < 1_000; i++) {
            byte[] temp = new byte[1_000_000];   // short-lived: reclaimed by young GCs
            if (i % 50 == 0) CACHE.put(i, temp); // retained: old gen keeps growing
        }
        Runtime rt = Runtime.getRuntime();
        long usedMb = (rt.totalMemory() - rt.freeMemory()) / 1_000_000;
        System.out.println("used ~" + usedMb + " MB, max " + rt.maxMemory() / 1_000_000 + " MB");
        // With -Xmx64m, raise the cached share and you'll hit OutOfMemoryError: Java heap space
    }
}

