// Run with: java -XX:+PrintCompilation Hot.java | grep -E "Hot::|made not entrant"
public class Hot {
    interface Shape { double area(); }
    record Sq(double s) implements Shape { public double area() { return s * s; } }
    record Circ(double r) implements Shape { public double area() { return Math.PI * r * r; } }

    static double total(Shape[] shapes) {
        double sum = 0;
        for (Shape s : shapes) sum += s.area();     // call site profiled for receiver types
        return sum;
    }

    public static void main(String[] args) {
        Shape[] squares = new Shape[1_000];
        for (int i = 0; i < squares.length; i++) squares[i] = new Sq(i % 10);
        for (int round = 0; round < 20_000; round++) total(squares); // monomorphic: inlined by C2

        Shape[] mixed = {new Sq(1), new Circ(1)};
        // A new receiver type at a speculated call site can trigger deoptimization
        // ("made not entrant") followed by recompilation as a bimorphic site.
        for (int round = 0; round < 20_000; round++) total(mixed);
        System.out.println(total(mixed));            // 4.141592653589793
    }
}

import java.util.ArrayList;
import java.util.List;

// Record:   java -XX:StartFlightRecording=duration=30s,filename=rec.jfr Profile.java
// Inspect:  jfr summary rec.jfr   |   jfr print --events jdk.ObjectAllocationSample rec.jfr
// Live:     jcmd <pid> Thread.print   |   jcmd <pid> GC.heap_info   (or open rec.jfr in JMC)
public class Profile {
    static long slow(int n) {                 // boxes every value: heavy allocation
        List<Long> values = new ArrayList<>();
        for (long i = 0; i < n; i++) values.add(i * i);
        long sum = 0;
        for (Long v : values) sum += v;
        return sum;
    }
    static long fast(int n) {                 // primitives only: no allocation
        long sum = 0;
        for (long i = 0; i < n; i++) sum += i * i;
        return sum;
    }

    public static void main(String[] args) {
        for (int i = 0; i < 50; i++) if (slow(2_000_000) != fast(2_000_000)) throw new AssertionError();
        System.out.println("done; the JFR allocation samples point at slow()");
    }
}
